import{_ as n,o as t,c as e,a3 as o}from"./chunks/framework.BwzYn71E.js";const p=JSON.parse('{"title":"Unifying Terminology and Building a Dictionary","description":"","frontmatter":{"translationSource":{"title":"各类术语的词义统一与词典制作","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=wE5eqNGummvOtoCzUO3RQK","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/unifying-terminology-and-building-a-dictionary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/unifying-terminology-and-building-a-dictionary"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/unifying-terminology-and-building-a-dictionary"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/unifying-terminology-and-building-a-dictionary"}]]},"headers":[],"relativePath":"unifying-terminology-and-building-a-dictionary.md","filePath":"logistics/src/page-wE5eqNGummvOtoCzUO3RQK.md"}'),r={name:"unifying-terminology-and-building-a-dictionary.md"};function a(s,i,l,u,c,d){return t(),e("div",null,[...i[0]||(i[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="各类术语的词义统一与词典制作" aria-hidden="true"></span><h1 id="unifying-terminology-and-building-a-dictionary" tabindex="-1">Unifying Terminology and Building a Dictionary <a class="header-anchor" href="#unifying-terminology-and-building-a-dictionary" aria-label="Permalink to &quot;Unifying Terminology and Building a Dictionary&quot;">​</a></h1><blockquote><p>Source page ID: <code>wE5eqNGummvOtoCzUO3RQK</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=wE5eqNGummvOtoCzUO3RQK" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span id="source-block-87n6trkPmz1YpdRnOZKk1M"></span></p><span class="logistics-source-anchor" id="波动分析" aria-hidden="true"></span><h4 id="fluctuation-analysis" tabindex="-1"><strong>Fluctuation Analysis</strong> <a class="header-anchor" href="#fluctuation-analysis" aria-label="Permalink to &quot;**Fluctuation Analysis**&quot;">​</a></h4><ul><li><strong>t_n</strong>: arrival time of item n at the output, n∈ℤ⁺; units: tick (1 tick = 2 seconds).</li><li><strong>T_avg</strong>: mean interval, lim_{n→∞} t_n/n, numerically L/K or 1/d; units: tick.</li><li><strong>M_dev</strong>: range of arrival-time deviation, sup_{n}(t_n - n·T_avg) - inf_{n}(t_n - n·T_avg); units: tick. Describes temporal flow stability and fluctuations in stored energy during generation.</li><li><strong>M_dev_bound</strong>: theoretical upper bound on that range; e.g. M_dev &lt; 2 means fluctuations below 2 tick (4 seconds).</li></ul><p><span id="source-block-nd8EFDucO3qUjzXot5uD3c"></span></p><span class="logistics-source-anchor" id="均匀度定义" aria-hidden="true"></span><h4 id="uniformity-definitions" tabindex="-1"><strong>Uniformity Definitions</strong> <a class="header-anchor" href="#uniformity-definitions" aria-label="Permalink to &quot;**Uniformity Definitions**&quot;">​</a></h4><ul><li><strong>Perfect uniformity</strong>: M_dev ≤ 1 (or strictly &lt;1), i.e. Bresenham-1 uniformity; a specialized term for proving leap-year-rule uniformity, not generally used.</li><li><strong>Bresenham-M uniformity</strong>: cumulative item count S_cum(n) satisfies ∀n: |S_cum(n) - d·n| &lt; M; M is the deviation bound.</li><li><strong>Beatty-M uniformity</strong>: interval item count S_cum(i,j) satisfies ∀i,j: |S_cum(i,j) - (j-i)·d| &lt; M. Equivalent to <strong>local uniformity</strong>: interval range relative to the most uniform case ≤1.</li><li><strong>Cipolla-M item-count uniformity</strong>: cumulative-deviation range satisfies sup_n(S_cum(n)-d·n) - inf_n(S_cum(n)-d·n) &lt; M.</li><li><strong>Cipolla-M time uniformity</strong>: arrival-time deviation range satisfies sup_n(t_n - n/d) - inf_n(t_n - n/d) &lt; M.</li></ul><p><span id="source-block-u0Z9YrEEmpvcjFnyhcJlra"></span></p><span class="logistics-source-anchor" id="序列与误差" aria-hidden="true"></span><h4 id="sequences-and-errors" tabindex="-1"><strong>Sequences and Errors</strong> <a class="header-anchor" href="#sequences-and-errors" aria-label="Permalink to &quot;**Sequences and Errors**&quot;">​</a></h4><ul><li><strong>t_i</strong>: position of the ith 1 in the output sequence, indexed from 1; i=1,...,K.</li><li><strong>L</strong>: sequence length, max(t_i), the position of the final 1; units: tick.</li><li><strong>K</strong>: number of 1s, or total items; originally N, changed to avoid conflict with counting-tree leaf count.</li><li><strong>d</strong>: duty cycle K/L, describing item density per unit time; units: items/tick.</li><li><strong>T_ideal</strong>: ideal interval L/K = 1/d, the theoretical mean spacing; units: tick.</li><li><strong>E(i)</strong>: ith output error t_i - i·T_ideal = k_i/K, an integer multiple of 1/K; deviation of actual from ideal position.</li></ul><p><span id="source-block-qGXqVRZXUne5DLsTLzkHQd"></span></p><span class="logistics-source-anchor" id="计数树与周期" aria-hidden="true"></span><h4 id="counting-trees-and-periods" tabindex="-1"><strong>Counting Trees and Periods</strong> <a class="header-anchor" href="#counting-trees-and-periods" aria-label="Permalink to &quot;**Counting Trees and Periods**&quot;">​</a></h4><ul><li><strong>N_leaf</strong>: counting-tree leaf count, 2^m·3^n, where m counts binary splitting nodes and n ternary ones.</li><li><strong>P_cycle</strong>: system period; for a recirculating counting tree, k·(N_leaf - |𝒮|) tick, where k is the external-input period parameter: one item every k tick.</li><li><strong>𝒮</strong>: Skip set, the counting values triggering recirculation; calligraphic S avoids confusion with cumulative count S_cum(n).</li><li><strong>𝒪</strong>: Output set, counting values triggering output.</li><li><strong>𝒫</strong>: Pass set, counting values triggering disposal.</li></ul><p><span id="source-block-YTu7OW8ti2uibRIzIxgPvL"></span></p><span class="logistics-source-anchor" id="蓄电量分析" aria-hidden="true"></span><h4 id="stored-energy-analysis" tabindex="-1"><strong>Stored-Energy Analysis</strong> <a class="header-anchor" href="#stored-energy-analysis" aria-label="Permalink to &quot;**Stored-Energy Analysis**&quot;">​</a></h4><ul><li><strong>E_n</strong>: stored energy at the instant the nth battery begins generating; units: joules.</li><li><strong>V</strong>: maximum stored energy during a period, V = sup_n E_n.</li><li><strong>ΔE</strong>: stored-energy range, E_max - E_min; theoretically ΔE &lt; 128000 - 40P + P·M_dev, in joules, where P is configured power.</li></ul><p><span id="source-block-uAA4vJGoG1SwzFwmGDrPX2"></span></p><span class="logistics-source-anchor" id="构造运算" aria-hidden="true"></span><h4 id="construction-operations" tabindex="-1"><strong>Construction Operations</strong> <a class="header-anchor" href="#construction-operations" aria-label="Permalink to &quot;**Construction Operations**&quot;">​</a></h4><ul><li><strong>Binary complementation</strong>: exchange 0 and 1; new duty cycle d&#39; = 1-d.</li><li><strong>K-fold thinning</strong>: retain the first of every K items; new duty cycle d&#39; = d/K.</li></ul><p><span id="source-block-QSfK3MpskztDYLzXXre8iH"></span></p><span class="logistics-source-anchor" id="优先级分析" aria-hidden="true"></span><h4 id="priority-analysis" tabindex="-1">Priority Analysis <a class="header-anchor" href="#priority-analysis" aria-label="Permalink to &quot;Priority Analysis&quot;">​</a></h4><ul><li><strong>Output priority</strong>: priority among outputs of stashes, individual factories, or Conduit Outlet Manifolds, as explained by damping theory or similar theories.</li><li><strong>Input priority</strong>: when a converger directly connects to a splitter, preferential acceptance of input from one direction.</li></ul><p><span id="source-block-N4r53hk8elxexgxAqqxLUd"></span></p><span class="logistics-source-anchor" id="常用词" aria-hidden="true"></span><h4 id="common-terms" tabindex="-1">Common Terms <a class="header-anchor" href="#common-terms" aria-label="Permalink to &quot;Common Terms&quot;">​</a></h4><ul><li><strong>Round-robin servicing</strong>:</li><li>Priority</li><li>231 theory</li></ul></div>',1)])])}const h=n(r,[["render",a]]);export{p as __pageData,h as default};
